#include <vector>
#include <numeric>
#include <algorithm>
#include <unordered_map>
using namespace std;

class Solution {
public:
    vector<int> smallestNegatedPermutation(vector<int>& nums, int target) {
        long long S = 0;
        for (int x : nums) S += x;
        if ((S + target) % 2 != 0 || S + target < 0) return {};
        long long P_target = (S + target) / 2;

        vector<int> sorted_nums = nums;
        sort(sorted_nums.begin(), sorted_nums.end());
        unordered_map<long long, vector<int>> dp;
        dp[0] = {};
        for (int x : sorted_nums) {
            auto next_dp = dp;
            for (auto& [s, items] : dp) {
                if (s + x <= P_target && !next_dp.count(s + x)) {
                    auto nitems = items;
                    nitems.push_back(x);
                    next_dp[s + x] = nitems;
                }
            }
            dp = move(next_dp);
        }
        if (!dp.count(P_target)) return {};
        vector<int> pos_items = dp[P_target];
        vector<int> rem = sorted_nums;
        for (int x : pos_items) {
            auto it = find(rem.begin(), rem.end(), x);
            if (it != rem.end()) rem.erase(it);
        }
        vector<int> res = pos_items;
        for (int x : rem) res.push_back(-x);
        sort(res.begin(), res.end());
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] smallestNegatedPermutation(int[] nums, int target) {
        long S = 0;
        for (int x : nums) S += x;
        if ((S + target) % 2 != 0 || S + target < 0) return new int[]{};
        long pTarget = (S + target) / 2;

        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        Map<Long, List<Integer>> dp = new HashMap<>();
        dp.put(0L, new ArrayList<>());
        for (int x : sorted) {
            Map<Long, List<Integer>> nextDp = new HashMap<>(dp);
            for (Map.Entry<Long, List<Integer>> entry : dp.entrySet()) {
                long s = entry.getKey();
                if (s + x <= pTarget && !nextDp.containsKey(s + x)) {
                    List<Integer> list = new ArrayList<>(entry.getValue());
                    list.add(x);
                    nextDp.put(s + x, list);
                }
            }
            dp = nextDp;
        }
        if (!dp.containsKey(pTarget)) return new int[]{};
        List<Integer> posItems = dp.get(pTarget);
        List<Integer> rem = new ArrayList<>();
        for (int x : sorted) rem.add(x);
        for (int x : posItems) rem.remove((Integer)x);

        List<Integer> resList = new ArrayList<>(posItems);
        for (int x : rem) resList.add(-x);
        Collections.sort(resList);
        int[] res = new int[resList.size()];
        for (int i = 0; i < resList.size(); i++) res[i] = resList.get(i);
        return res;
    }
}

var smallestNegatedPermutation = function(nums, target) {
    let S = 0;
    for (const x of nums) S += x;
    if ((S + target) % 2 !== 0 || S + target < 0) return [];
    const pTarget = Math.floor((S + target) / 2);

    const sorted = [...nums].sort((a, b) => a - b);
    let dp = new Map();
    dp.set(0, []);
    for (const x of sorted) {
        const nextDp = new Map(dp);
        for (const [s, items] of dp.entries()) {
            if (s + x <= pTarget && !nextDp.has(s + x)) {
                nextDp.set(s + x, [...items, x]);
            }
        }
        dp = nextDp;
    }
    if (!dp.has(pTarget)) return [];
    const posItems = dp.get(pTarget);
    const rem = [...sorted];
    for (const x of posItems) {
        const idx = rem.indexOf(x);
        if (idx !== -1) rem.splice(idx, 1);
    }
    const res = [...posItems, ...rem.map(x => -x)].sort((a, b) => a - b);
    return res;
};
